static void *get_data_from_list_entry(LIST_ENTRY *list_entry)
{
    return (unsigned char *)list_entry + FIELD_OFFSET(struct rtl_generic_table_entry, data)
        - FIELD_OFFSET(struct rtl_generic_table_entry, list_entry);
}

